/* From Uiverse.io by JkHuger - Tags: loader */
.__UIV_SCOPE__ .container {
  width: 80px;
  margin: 100px auto;
}

.__UIV_SCOPE__ .block {
  position: relative;
  box-sizing: border-box;
  float: left;
  margin: 0 10px 10px 0;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  background: #FFF;
}

.__UIV_SCOPE__ .block:nth-child(4n+1) {
  animation: wave_23 2s ease .0s infinite;
}

.__UIV_SCOPE__ .block:nth-child(4n+2) {
  animation: wave_23 2s ease .2s infinite;
}

.__UIV_SCOPE__ .block:nth-child(4n+3) {
  animation: wave_23 2s ease .4s infinite;
}

.__UIV_SCOPE__ .block:nth-child(4n+4) {
  animation: wave_23 2s ease .6s infinite;
  margin-right: 0;
}

@keyframes wave_23 {
  0% {
    top: 0;
    opacity: 1;
  }

  50% {
    top: 30px;
    opacity: .2;
  }

  100% {
    top: 0;
    opacity: 1;
  }
}
